-- AarogyaLink mock data: 693 patients (generated by build_seed_700.py, do not edit by hand).
-- 7 more patients (6 demo + Mudit Jha) are added by seed_demo_consents.sql -> 700 in total.
BEGIN;
-- Explicit audit_log ids below would collide with rows the visit trigger generates.
ALTER TABLE visit DISABLE TRIGGER tr_visit_audit;










ALTER TABLE visit ENABLE TRIGGER tr_visit_audit;

SELECT setval('visit_visit_id_seq', (SELECT COALESCE(MAX(visit_id), 0) + 1 FROM visit), false);
SELECT setval('diagnosis_diagnosis_id_seq', (SELECT COALESCE(MAX(diagnosis_id), 0) + 1 FROM diagnosis), false);
SELECT setval('prescription_prescription_id_seq', (SELECT COALESCE(MAX(prescription_id), 0) + 1 FROM prescription), false);
SELECT setval('lab_test_lab_test_id_seq', (SELECT COALESCE(MAX(lab_test_id), 0) + 1 FROM lab_test), false);
SELECT setval('consent_consent_id_seq', (SELECT COALESCE(MAX(consent_id), 0) + 1 FROM consent), false);
SELECT setval('audit_log_log_id_seq', (SELECT COALESCE(MAX(log_id), 0) + 1 FROM audit_log), false);
COMMIT;
